INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Superman', 'Superman is an action adventure game for the Atari 2600. It was one of the first single-player games for the system and one of the earliest licensed video games. Superman is one of the first to utilize multiple screens as playing areas.' FROM games WHERE igdb_id = 18711 ON CONFLICT (game_id, language_code) DO NOTHING;
