INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('pro-golf', 95358, '1979-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co76ag.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scotas.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pro Golf', 'Pro Golf 1 is a single player golf game featuring an eighteen hole golf course. Each hole is drawn using the Apple II''s low resolution graphics mode and includes hazards such as water and sand traps. The keyboard is used to play the game. First the player has to enter which club to use and then shots are taken by entering the angle (0-360) of each shot. When putting, the length of the put is also entered. The game consists of three parts: front nine, back nine and an intro. The first two include all the holes of the Silicon Pines Golf Course while the intro program contains instructions as well as a driving range and a putting green.' FROM games WHERE igdb_id = 95358 ON CONFLICT (game_id, language_code) DO NOTHING;
